<script setup lang="ts">import UserAvatar from './UserAvatar.vue';import ScoreBadge from './ScoreBadge.vue';import type {CrmLead,LeadStage} from '@/types/crm';const p=defineProps<{leads:CrmLead[]}>();const emit=defineEmits<{move:[id:string,stage:LeadStage];open:[id:string]}>();const stages:LeadStage[]=['New','Contacted','Qualified','Proposal','Negotiation','Won','Lost'];function drop(e:DragEvent,s:LeadStage){const id=e.dataTransfer?.getData('text/plain');if(id)emit('move',id,s)};</script>
<template><div class="overflow-x-auto pb-2"><div class="grid min-w-[1540px] grid-cols-7 gap-3"><section v-for="stage in stages" :key="stage" class="rounded-md bg-surface-sunken p-2" @dragover.prevent @drop="drop($event,stage)"><header class="mb-2 flex items-center justify-between px-1"><span class="label-caps">{{stage}}</span><span class="num text-2xs text-content-muted">{{leads.filter(l=>l.stage===stage).length}}</span></header><div class="space-y-2"><article v-for="lead in leads.filter(l=>l.stage===stage)" :key="lead.id" draggable="true" class="cursor-grab rounded-md border border-line bg-surface p-3 shadow-xs active:cursor-grabbing" @dragstart="$event.dataTransfer?.setData('text/plain',lead.id)" @click="$emit('open',lead.id)"><div class="flex items-start justify-between gap-2"><div><p class="text-xs font-semibold text-content">{{lead.company}}</p><p class="mt-0.5 text-2xs text-content-muted">{{lead.name}}</p></div><ScoreBadge :score="lead.score.total" :label="''"/></div><p class="num mt-3 text-sm font-semibold text-content">PKR {{(lead.value/1000000).toFixed(1)}}M</p><div class="mt-3 flex items-center gap-2"><UserAvatar :name="lead.owner" size="sm"/><span class="truncate text-2xs text-content-muted">{{lead.owner}}</span></div><p class="mt-2 text-2xs text-content-muted">Last activity {{lead.lastActivity}}</p></article></div></section></div></div></template>
